const conflict = (correctionId: StockCorrectionId, reason: StockCorrectionConflict['reason']) =>
  new StockCorrectionConflict({ code: 'stock_correction_conflict', correctionId, reason });

const rejected = (correctionId: StockCorrectionId, reason: StockCorrectionRejected['reason']) =>
  new StockCorrectionRejected({ code: 'stock_correction_rejected', correctionId, reason });

const unavailable = (correctionId: StockCorrectionId, reason: string, cause?: unknown) => {
  const failure = new StockCorrectionUnavailable({
    code: 'stock_correction_unavailable',
    correctionId,
    reason,
    retryable: true,
  });
  if (cause !== undefined) {
    Object.defineProperty(failure, 'cause', { configurable: true, value: cause });
  }
  return failure;
};

const sameRef = (
  left: { readonly resourceId: string; readonly tenantId: string },
  right: { readonly resourceId: string; readonly tenantId: string },
) => left.resourceId === right.resourceId && left.tenantId === right.tenantId;

const sameUnit = (left: StockPosition['scope']['unitRef'], right: StockPosition['scope']['unitRef']) =>
  left.moduleId === right.moduleId &&
  left.resourceId === right.resourceId &&
  left.resourceType === right.resourceType &&
  left.tenantId === right.tenantId;

const sameCorrectionIntent = (record: StockCorrectionRecord, payload: StockCorrectionPayload): boolean =>
  record.correctionId === payload.correctionId &&
  record.customerConfigurationId === payload.customerConfigurationId &&
  record.expectedPositionRevision === payload.expectedPositionRevision &&
  sameRef(record.positionRef, payload.positionRef) &&
  record.reason.code === payload.reason.code &&
  record.reason.reference === payload.reason.reference &&
  record.reconcilesCorrectionId === (payload.reconcilesCorrectionId ?? null) &&
  Match.value(payload.evidence).pipe(
    Match.tag(
      'EXTERNAL_SOURCE_ASSERTION',
      ({ sourceAssertionId }) =>
        record.evidenceKind === 'EXTERNAL_SOURCE_ASSERTION' && record.sourceAssertionId === sourceAssertionId,
    ),
    Match.tag(
      'ONTOS_WMS_OWNER_EVIDENCE',
      ({ evidenceId }) => record.evidenceKind === 'ONTOS_WMS_OWNER_EVIDENCE' && record.sourceEvidenceId === evidenceId,
    ),
    Match.exhaustive,
  );

/**
 * Capability comes only from server-owned Source Assertion provenance for the selected backend.
 * The public Correction payload deliberately has no authority or coverage override.
 */
const selectedBackendPermitsCorrection = (
  evidence: Pick<ResolvedCorrectionEvidence, 'authorityConfiguration' | 'issuer'>,
  configuration: InventorySourceAssertion['authorityConfiguration'],
): boolean =>
  configuration.selection.stockCorrectionCapability === 'SUPPORTED' &&
  evidence.authorityConfiguration.configurationId === configuration.configurationId &&
  evidence.authorityConfiguration.selection.backend === configuration.selection.backend &&
  evidence.authorityConfiguration.selection.backendId === configuration.selection.backendId &&
  evidence.issuer.backendKind === configuration.selection.backend &&
  evidence.issuer.backendId === configuration.selection.backendId;

const sourceAssertionIsAcceptedCurrent = (
  assertion: InventorySourceAssertion,
  acceptedHistory: readonly InventorySourceImportLedgerEntry[],
): boolean => {
  const accepted = acceptedHistory.filter(({ outcome }) => outcome.status === 'ACCEPTED');
  if (!accepted.some(({ proposal }) => proposal.assertionId === assertion.assertionId)) {
    return false;
  }
  return accepted.every(({ proposal }) => {
    const relation = compareInventorySourceOrdering(assertion.orderingEvidence, proposal.orderingEvidence);
    return relation === 'SAME' || relation === 'NEWER';
  });
};

interface ResolvedCorrectionEvidence {
  readonly authorityConfiguration: InventorySourceAssertion['authorityConfiguration'];
  readonly businessObservedAt: InventorySourceAssertion['businessObservedAt'];
  readonly coverage: StockCorrectionRecord['coverageEvidence'];
  readonly evidenceKind: StockCorrectionRecord['evidenceKind'];
  readonly issuer: { readonly backendId: string; readonly backendKind: 'external_business_system' | 'ontos_wms' };
  readonly orderingEvidence: InventorySourceAssertion['orderingEvidence'];
  readonly ownerEvidenceRef: string;
  readonly positionRef: InventorySourceAssertion['positionRef'];
  readonly quantity: InventorySourceAssertion['quantity'];
  readonly sourceAssertionId?: InventorySourceAssertion['assertionId'];
  readonly sourceEvidenceId?: StockCorrectionSourceEvidenceId;
  readonly sourceReference: string;
  readonly stockItemRef: InventorySourceAssertion['stockItemRef'];
  readonly stockLocationRef: InventorySourceAssertion['stockLocationRef'];
}

const relevantInterveningEffects = (
  assertion: ResolvedCorrectionEvidence,
  effects: readonly PhysicalStockEffectRecord[],
) =>
  effects.filter(
    (effect) =>
      Schema.is(AppliedPhysicalStockEffectSchema)(effect) &&
      DateTime.toEpochMillis(DateTime.makeUnsafe(effect.evidence.appliedAt)) >=
        DateTime.toEpochMillis(DateTime.makeUnsafe(assertion.businessObservedAt)) &&
      sameRef(effect.request.positionRef, assertion.positionRef) &&
      sameRef(effect.request.stockItemRef, assertion.stockItemRef) &&
      sameRef(effect.request.stockLocationRef, assertion.stockLocationRef) &&
      sameUnit(effect.request.quantity.unitRef, assertion.quantity.unitRef),
  );

const evaluateInterveningCoverage = (
  assertion: ResolvedCorrectionEvidence,
  effects: readonly PhysicalStockEffectRecord[],
) => {
  const relevant = relevantInterveningEffects(assertion, effects);
  const coverage = new Map(assertion.coverage.map((entry) => [entry.effectId, entry.relation]));
  const missing = relevant.filter((effect) => coverage.get(effect.request.effectId) === undefined);
  if (missing.length > 0) {
    return {
      materialEffectIds: missing.map((effect) => effect.request.effectId),
      reasonCode: 'MATERIAL_EFFECT_COVERAGE_MISSING' as const,
    };
  }
  const unknown = relevant.filter((effect) => coverage.get(effect.request.effectId) === 'UNKNOWN');
  if (unknown.length > 0) {
    return {
      materialEffectIds: unknown.map((effect) => effect.request.effectId),
      reasonCode: 'MATERIAL_EFFECT_COVERAGE_UNKNOWN' as const,
    };
  }
  const excluded = relevant.filter((effect) => {
    const relation = coverage.get(effect.request.effectId);
    return relation === 'EXCLUDES' || relation === 'PREDATES';
  });
  return excluded.length === 0
    ? undefined
    : {
        materialEffectIds: excluded.map((effect) => effect.request.effectId),
        reasonCode: 'MATERIAL_EFFECT_EXCLUDED_OR_PREDATED' as const,
      };
};

const previousQuantity = (onHand: StockPositionOnHandEvidence) =>
  Match.value(onHand).pipe(
    Match.tag('CURRENT', ({ quantity }) => quantity),
    Match.tag('STALE', ({ lastKnownQuantity }) => lastKnownQuantity),
    // oxlint-disable-next-line unicorn/no-useless-undefined -- Match branches require one explicit absent value for unavailable evidence variants.
    Match.tag('UNKNOWN', 'MISSING', 'INDETERMINATE', () => undefined),
    Match.exhaustive,
  );

const materialChangeForDelta = (delta: string | undefined) => {
  if (delta === undefined) {
    return 'UNRESOLVED_BASELINE' as const;
  }
  if (delta === '0') {
    return 'UNCHANGED' as const;
  }
  return delta.startsWith('-') ? ('DECREASE' as const) : ('INCREASE' as const);
};

const replayResult = (correction: StockCorrectionRecord, position: StockPosition): StockCorrectionResult => ({
  correction,
  outcome: 'EXACT_REPLAY',
  position,
});

// oxlint-disable-next-line effect-native/no-dependency-parameters, effect-native/no-wide-factory-signature -- Core supplies exact owner-local transaction ports to the generated Action factory; expires: 2027-03-31.
export const makeStockCorrectionService = (dependencies: StockCorrectionDependencies): StockCorrectionService => ({
  // oxlint-disable-next-line eslint/complexity -- This owner service keeps the ordered fail-closed authority, scope, coverage, reconciliation, and optimistic-write checks visible in one transaction; expires: 2027-03-31.
  correct: Effect.fn('StockCorrectionService.correct')(function* correctPosition(payload, context) {
    if (payload.positionRef.tenantId !== context.tenantId) {
      return yield* rejected(payload.correctionId, 'TENANT_SCOPE_MISMATCH');
    }
    const existing = yield* dependencies.corrections
      .read(payload.correctionId)
      .pipe(
        Effect.mapError((cause) =>
          unavailable(payload.correctionId, 'Stock Correction evidence is unavailable', cause),
        ),
      );
    if (Option.isSome(existing)) {
      if (!sameCorrectionIntent(existing.value, payload)) {
        return yield* conflict(payload.correctionId, 'CORRECTION_ID_CONFLICT');
      }
      const position = yield* dependencies.positions.read(payload.positionRef).pipe(
        Effect.mapError((cause) => unavailable(payload.correctionId, 'Stock Position evidence is unavailable', cause)),
        Effect.flatMap(
          Option.match({
            onNone: () => Effect.fail(rejected(payload.correctionId, 'POSITION_NOT_FOUND')),
            onSome: Effect.succeed,
          }),
        ),
      );
      if (Schema.is(AppliedStockCorrectionSchema)(existing.value) && existing.value.materialChange !== 'UNCHANGED') {
        yield* dependencies.impacts
          .evaluate({
            changeId: existing.value.correctionId,
            changeKind: 'CORRECTION',
            occurredAt: existing.value.appliedAt,
            positionRef: existing.value.positionRef,
          })
          .pipe(
            Effect.mapError((cause) =>
              unavailable(payload.correctionId, 'Reservation shortage impact evaluation is unavailable', cause),
            ),
          );
      }
      return replayResult(existing.value, position);
    }

    const position = yield* dependencies.positions.read(payload.positionRef).pipe(
      Effect.mapError((cause) => unavailable(payload.correctionId, 'Stock Position evidence is unavailable', cause)),
      Effect.flatMap(
        Option.match({
          onNone: () => Effect.fail(rejected(payload.correctionId, 'POSITION_NOT_FOUND')),
          onSome: Effect.succeed,
        }),
      ),
    );
    if (position.lifecycle !== 'CURRENT') {
      return yield* rejected(payload.correctionId, 'POSITION_NOT_CURRENT');
    }
    if (position.revision !== payload.expectedPositionRevision) {
      return yield* conflict(payload.correctionId, 'POSITION_REVISION_CONFLICT');
    }
    if (position.scope.customerConfigurationId !== payload.customerConfigurationId) {
      return yield* rejected(payload.correctionId, 'CUSTOMER_CONFIGURATION_MISMATCH');
    }

    const openReconciliation = yield* dependencies.corrections
      .findOpenIndeterminate(payload.positionRef)
      .pipe(
        Effect.mapError((cause) =>
          unavailable(payload.correctionId, 'Correction reconciliation state is unavailable', cause),
        ),
      );
    if (Option.isSome(openReconciliation) && openReconciliation.value.correctionId !== payload.reconcilesCorrectionId) {
      return yield* conflict(payload.correctionId, 'OPEN_RECONCILIATION_MISMATCH');
    }
    if (Option.isNone(openReconciliation) && payload.reconcilesCorrectionId !== undefined) {
      return yield* conflict(payload.correctionId, 'OPEN_RECONCILIATION_MISMATCH');
    }

    const configuration = yield* dependencies.backendConfigurations.findCurrent(payload.customerConfigurationId).pipe(
      Effect.mapError((cause) => unavailable(payload.correctionId, 'Selected Inventory Backend is unavailable', cause)),
      Effect.flatMap(
        Option.match({
          onNone: () => Effect.fail(rejected(payload.correctionId, 'AUTHORITY_NOT_SELECTED')),
          onSome: Effect.succeed,
        }),
      ),
    );
    if (configuration.tenantId !== context.tenantId) {
      return yield* rejected(payload.correctionId, 'TENANT_SCOPE_MISMATCH');
    }

    /* oxlint-disable sonarjs/no-nested-functions -- Branch-local Effect composition keeps both trusted evidence resolvers explicit and fail-closed; expires: 2027-03-31. */
    const evidence: ResolvedCorrectionEvidence = yield* Match.value(payload.evidence).pipe(
      Match.tag('EXTERNAL_SOURCE_ASSERTION', ({ sourceAssertionId }) =>
        dependencies.assertions.findById(sourceAssertionId).pipe(
          Effect.mapError((cause) =>
            unavailable(payload.correctionId, 'Source Assertion evidence is unavailable', cause),
          ),
          Effect.flatMap(
            Option.match({
              onNone: () => Effect.fail(rejected(payload.correctionId, 'SOURCE_ASSERTION_NOT_FOUND')),
              onSome: Effect.succeed,
            }),
          ),
          Effect.flatMap((assertion) =>
            dependencies.sourceImports.lockAndReadAcceptedHistory(assertion).pipe(
              Effect.mapError((cause) =>
                unavailable(payload.correctionId, 'Source Assertion currentness is unavailable', cause),
              ),
              Effect.flatMap((history) =>
                sourceAssertionIsAcceptedCurrent(assertion, history)
                  ? Effect.succeed(assertion)
                  : Effect.fail(rejected(payload.correctionId, 'SOURCE_ASSERTION_NOT_CURRENT')),
              ),
            ),
          ),
          Effect.flatMap((assertion) =>
            assertion.issuerAuthority === 'SELECTED_BACKEND'
              ? Effect.succeed({
                  ...assertion,
                  evidenceKind: 'EXTERNAL_SOURCE_ASSERTION' as const,
                  sourceAssertionId: assertion.assertionId,
                })
              : Effect.fail(rejected(payload.correctionId, 'CORRECTION_NOT_PERMITTED')),
          ),
        ),
      ),
      Match.tag('ONTOS_WMS_OWNER_EVIDENCE', ({ evidenceId }) =>
        dependencies.sourceEvidence.findCurrentById(evidenceId).pipe(
          Effect.mapError((cause) =>
            unavailable(payload.correctionId, 'OntOS WMS correction evidence is unavailable', cause),
          ),
          Effect.flatMap(
            Option.match({
              onNone: () => Effect.fail(rejected(payload.correctionId, 'SOURCE_ASSERTION_NOT_CURRENT')),
              onSome: Effect.succeed,
            }),
          ),
          Effect.map((ownerEvidence) => ({
            ...ownerEvidence,
            evidenceKind: 'ONTOS_WMS_OWNER_EVIDENCE' as const,
            sourceEvidenceId: ownerEvidence.evidenceId,
          })),
        ),
      ),
      Match.exhaustive,
    );
    /* oxlint-enable sonarjs/no-nested-functions */
    if (
      !sameRef(evidence.positionRef, position.ref) ||
      !sameRef(evidence.stockItemRef, position.scope.stockItemRef) ||
      !sameRef(evidence.stockLocationRef, position.scope.stockLocationRef) ||
      evidence.authorityConfiguration.customerConfigurationId !== payload.customerConfigurationId
    ) {
      return yield* rejected(payload.correctionId, 'SOURCE_ASSERTION_SCOPE_MISMATCH');
    }
    if (!sameUnit(evidence.quantity.unitRef, position.scope.unitRef)) {
      return yield* rejected(payload.correctionId, 'UNIT_MISMATCH');
    }
    if (!selectedBackendPermitsCorrection(evidence, configuration)) {
      return yield* rejected(payload.correctionId, 'CORRECTION_NOT_PERMITTED');
    }

    const effects = yield* dependencies.corrections
      .listAppliedEffectsForPosition(payload.positionRef)
      .pipe(
        Effect.mapError((cause) =>
          unavailable(payload.correctionId, 'Material physical effects are unavailable', cause),
        ),
      );
    const interveningEffects = relevantInterveningEffects(evidence, effects);
    const coverageFailure = evaluateInterveningCoverage(evidence, effects);
    const now = DateTime.formatIso(yield* DateTime.now);
    const base = {
      actionInvocationId: context.actionInvocationId,
      appliedAt: now,
      authorityConfigurationRef: {
        moduleId: 'commerce.inventory' as const,
        resourceId: configuration.configurationId,
        resourceType: 'commerce.inventory.inventory-backend-configuration' as const,
        tenantId: configuration.tenantId,
      },
      businessObservedAt: evidence.businessObservedAt,
      correctionId: payload.correctionId,
      coverageEvidence: evidence.coverage,
      customerConfigurationId: payload.customerConfigurationId,
      evaluatedMaterialEffectIds: interveningEffects.map((effect) => effect.request.effectId),
      evidenceKind: evidence.evidenceKind,
      expectedPositionRevision: payload.expectedPositionRevision,
      issuer: evidence.issuer,
      ownerEvidenceRef: evidence.ownerEvidenceRef,
      positionRef: payload.positionRef,
      positionRevisionAfter: payload.expectedPositionRevision + 1,
      previousOnHand: position.onHand,
      principalId: context.principalId,
      reason: payload.reason,
      reconcilesCorrectionId: payload.reconcilesCorrectionId ?? null,
      sourceAssertionId: evidence.sourceAssertionId ?? null,
      sourceEvidenceId: evidence.sourceEvidenceId ?? null,
      sourceOrderingEvidence: evidence.orderingEvidence,
      sourceReference: evidence.sourceReference,
    };

    if (coverageFailure !== undefined) {
      const correction = yield* Schema.decodeEffect(IndeterminateStockCorrectionSchema)({
        ...base,
        _tag: 'INDETERMINATE',
        ...coverageFailure,
      }).pipe(Effect.mapError((cause) => unavailable(payload.correctionId, 'Correction evidence is invalid', cause)));
      const nextPosition = yield* recordOnHandEvidence(position, {
        _tag: 'INDETERMINATE',
        meaning: 'ON_HAND',
        ownerConfigurationRef: base.authorityConfigurationRef,
        unitRef: position.scope.unitRef,
      }).pipe(Effect.mapError((cause) => unavailable(payload.correctionId, 'Stock Position update is invalid', cause)));
      const stored = yield* dependencies.corrections.apply(
        correction,
        nextPosition,
        payload.expectedPositionRevision,
        payload.reconcilesCorrectionId,
      );
      if (!sameCorrectionIntent(stored.correction, payload)) {
        return yield* conflict(payload.correctionId, 'CORRECTION_ID_CONFLICT');
      }
      return {
        correction: stored.correction,
        outcome: stored.outcome === 'EXISTING' ? 'EXACT_REPLAY' : 'RECONCILIATION_REQUIRED',
        position: stored.position,
      };
    }

    const prior = previousQuantity(position.onHand);
    const delta =
      prior === undefined
        ? undefined
        : yield* deriveStockCorrectionDelta(prior.amount, evidence.quantity.amount).pipe(
            Effect.mapError((cause) => unavailable(payload.correctionId, 'Correction delta is invalid', cause)),
          );
    const materialChange = materialChangeForDelta(delta);
    const correction = yield* Schema.decodeEffect(AppliedStockCorrectionSchema)({
      ...base,
      _tag: 'APPLIED',
      correctedQuantity: evidence.quantity,
      explanatoryDelta: delta ?? null,
      materialChange,
    }).pipe(Effect.mapError((cause) => unavailable(payload.correctionId, 'Correction evidence is invalid', cause)));
    const nextPosition = yield* recordOnHandEvidence(position, {
      _tag: 'CURRENT',
      evidenceRef: evidence.ownerEvidenceRef,
      meaning: 'ON_HAND',
      observedAt: evidence.businessObservedAt,
      ownerConfigurationRef: base.authorityConfigurationRef,
      quantity: evidence.quantity,
    }).pipe(Effect.mapError((cause) => unavailable(payload.correctionId, 'Stock Position update is invalid', cause)));
    const stored = yield* dependencies.corrections.apply(
      correction,
      nextPosition,
      payload.expectedPositionRevision,
      payload.reconcilesCorrectionId,
    );
    if (!sameCorrectionIntent(stored.correction, payload)) {
      return yield* conflict(payload.correctionId, 'CORRECTION_ID_CONFLICT');
    }
    if (
      Schema.is(AppliedStockCorrectionSchema)(stored.correction) &&
      stored.correction.materialChange !== 'UNCHANGED'
    ) {
      yield* dependencies.impacts
        .evaluate({
          changeId: stored.correction.correctionId,
          changeKind: 'CORRECTION',
          occurredAt: stored.correction.appliedAt,
          positionRef: stored.correction.positionRef,
        })
        .pipe(
          Effect.mapError((cause) =>
            unavailable(payload.correctionId, 'Reservation shortage impact evaluation is unavailable', cause),
          ),
        );
    }
    return {
      correction: stored.correction,
      outcome: stored.outcome === 'EXISTING' ? 'EXACT_REPLAY' : 'APPLIED',
      position: stored.position,
    };
  }),
});
